adcs_status_t st;
adcs_vec3_t u_ba, u_bb, u_ia, u_ib;
double cos_b, cos_i, ang_b, ang_i, na, nb, ni, nj;

if ((body_a == NULL) || (body_b == NULL) || (inertial_a == NULL) ||
    (inertial_b == NULL) || (mismatch_rad == NULL)) {
    return ADCS_E_NULL;
}

*mismatch_rad = INFINITY;

if ((!adcs_is_finite_vec3(body_a)) || (!adcs_is_finite_vec3(body_b)) ||
    (!adcs_is_finite_vec3(inertial_a)) || (!adcs_is_finite_vec3(inertial_b))) {
    return ADCS_E_DEGENERATE;
}

na = adcs_vec3_norm(body_a);
nb = adcs_vec3_norm(body_b);
ni = adcs_vec3_norm(inertial_a);
nj = adcs_vec3_norm(inertial_b);

if ((!isfinite(na)) || (!isfinite(nb)) || (!isfinite(ni)) || (!isfinite(nj)) ||
    (na <= ADCS_EPS_NORM) || (nb <= ADCS_EPS_NORM) ||
    (ni <= ADCS_EPS_NORM) || (nj <= ADCS_EPS_NORM)) {
    return ADCS_E_DEGENERATE;
}

u_ba = adcs_vec3_scale(body_a, 1.0 / na);
u_bb = adcs_vec3_scale(body_b, 1.0 / nb);
u_ia = adcs_vec3_scale(inertial_a, 1.0 / ni);
u_ib = adcs_vec3_scale(inertial_b, 1.0 / nj);

cos_b = adcs_vec3_dot(&u_ba, &u_bb);
cos_i = adcs_vec3_dot(&u_ia, &u_ib);

cos_b = ADCS_CLAMP(cos_b, 0.0, 1.0);
cos_i = ADCS_CLAMP(cos_i, 0.0, 1.0);

ang_b = acos(cos_b);
ang_i = acos(cos_i);

*mismatch_rad = fabs(ang_b - ang_i);

st = ADCS_OK;
return st;
}

